#include "transport_web.h"
#include "hub.h"
#include <WiFi.h>
#include <WebServer.h>
#include <DNSServer.h>
#include "web_page.h"          // generated by tools/build_web.py — include from this TU only

// Threading: every handler below runs on the core-0 net task (poll() -> handleClient()).
// The JsonDocuments are created and destroyed inside the handler; shared hub state is read
// through hub:: (which copies under its own locks). Stats are plain 32-bit volatiles.
//
// POST /cmd body: with `Content-Type: application/json` the core WebServer exposes the raw
// body as arg("plain"). A bare `curl -d '{...}'` sends x-www-form-urlencoded; the server then
// parses the body as form fields, so we rebuild it from the first field (name[=value]) — good
// enough for JSON without '&', '+' or '='. Every /cmd reply is HTTP 200; errors are in the JSON.

namespace transport_web {

static WebServer  server(80);
static DNSServer  dns;
static CmdHandler handler = nullptr;

static volatile uint32_t reqs = 0;
static volatile uint32_t lastIp = 0;
static volatile uint8_t  staCount = 0;
static uint32_t lastStaAt = 0;

static void noteRequest() {
  reqs = reqs + 1;
  lastIp = (uint32_t)server.client().remoteIP();
}

static void jsonHeaders() {
  server.sendHeader("Cache-Control", "no-store");
  server.sendHeader("Access-Control-Allow-Origin", "*");
}

static void handleRoot() {
  noteRequest();
  server.sendHeader("Content-Encoding", "gzip");
  server.sendHeader("Cache-Control", "no-store");
  server.send_P(200, "text/html", (PGM_P)WEB_INDEX_GZ, WEB_INDEX_GZ_LEN);
}

static void redirectRoot() {
  noteRequest();
  server.sendHeader("Location", "http://192.168.4.1/", true);
  server.sendHeader("Cache-Control", "no-store");
  server.send(302, "text/plain", "");
}

static void handleState() {
  noteRequest();
  JsonDocument doc;
  hub::buildState(doc.to<JsonObject>());
  String out; out.reserve(1536);
  serializeJson(doc, out);
  jsonHeaders();
  server.send(200, "application/json", out);
}

static void handleCmd() {
  noteRequest();
  String body = server.arg("plain");
  if (body.length() == 0 && server.args() > 0) {          // x-www-form-urlencoded fallback (bare curl -d)
    body = server.argName(0);
    if (server.arg(0).length()) { body += '='; body += server.arg(0); }
  }
  JsonDocument reply;
  if (body.length() > CMD_MAX_BODY) {
    reply["ok"] = false; reply["err"] = "bad_json"; reply["note"] = "body > 512 B";
  } else {
    JsonDocument cmd;
    DeserializationError e = deserializeJson(cmd, body);
    if (e || !cmd.is<JsonObject>()) {
      reply["ok"] = false; reply["err"] = "bad_json";
    } else {
      bool ok = handler ? handler(cmd, reply) : false;
      if (!ok && reply["err"].isNull()) reply["err"] = "bad_cmd";
      reply["ok"] = ok;
    }
  }
  String out; out.reserve(1536);
  serializeJson(reply, out);
  jsonHeaders();
  server.send(200, "application/json", out);
  Serial.printf("[WEB] POST /cmd %.120s -> %.160s\n", body.c_str(), out.c_str());
}

static void handleNotFound() {
  Serial.printf("[WEB] %s %s -> 302 /\n", server.method() == HTTP_POST ? "POST" : "GET", server.uri().c_str());
  redirectRoot();
}

struct WebTransport : public Transport {
  void begin() override {
    IPAddress ip = WiFi.softAPIP();
    dns.start(53, "*", ip);
    server.on("/", HTTP_GET, handleRoot);
    server.on("/index.html", HTTP_GET, handleRoot);
    server.on("/cmd", HTTP_POST, handleCmd);
    server.on("/state", HTTP_GET, handleState);
    static const char* const PROBES[] = { "/generate_204", "/gen_204", "/hotspot-detect.html", "/library/test/success.html",
                                          "/connecttest.txt", "/ncsi.txt", "/fwlink", "/redirect", "/success.txt",
                                          "/canonical.html", "/check_network_status.txt" };
    for (auto p : PROBES) server.on(p, HTTP_ANY, redirectRoot);
    server.onNotFound(handleNotFound);
    server.begin();
    Serial.printf("[WEB] listening on %s (SSID %s)\n", ip.toString().c_str(), WiFi.softAPSSID().c_str());
  }
  void poll() override {
    server.handleClient();
    dns.processNextRequest();
    uint32_t now = millis();
    if (now - lastStaAt >= 1000) { lastStaAt = now; staCount = WiFi.softAPgetStationNum(); }
  }
  void sendEvent(const char*) override {}
  void setCommandHandler(CmdHandler fn) override { handler = fn; }
};

static WebTransport inst;
Transport& instance() { return inst; }

uint32_t reqCount()     { return reqs; }
uint32_t lastClientIp() { return lastIp; }
uint8_t  apClients()    { return staCount; }

} // namespace transport_web
